// === Tab: mySketch ===
let particles = [];
let centers = [];
let symmetry = 6;
let palette = ["#8390FA", "#FAC748", "#F9E9EC", "#F88DAD"];

function setup() {
  createCanvas(400, 400);
  angleMode(RADIANS);
  background(255);
  centers.push(createVector(width / 2, height / 2));
  spawnSeed(centers[0]);
}

function draw() {
  noStroke();
  fill(255, 255, 255, 5); // slow fading trail
  rect(0, 0, width, height);

  // Iterate backwards to safely remove fading particles
  for (let i = particles.length - 1; i >= 0; i--) {
    let p = particles[i];
    p.update();
    p.display();
    if (p.alpha <= 0) {
      particles.splice(i, 1);
    }
  }
}

function mousePressed() {
  let newCenter = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  centers.push(newCenter);
  spawnSeed(newCenter);
}

function spawnSeed(origin) {
  let growthLimit = floor(random(10, 40));
  for (let i = 0; i < 5; i++) {
    let angle = random(TWO_PI);
    let r = random(5, 15);
    let x = origin.x + r * cos(angle);
    let y = origin.y + r * sin(angle);
    particles.push(new Particle(x, y, origin, false, growthLimit));
  }
}

class Particle {
  constructor(x, y, origin, stuck = false, growthLimit = 20) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.random2D().mult(random(0.2, 0.5));
    this.r = 2;
    this.origin = origin.copy();
    this.stuck = stuck;
    this.hue = color(random(palette));
    this.hasSpawned = false;
    this.growthLimit = growthLimit;
    this.fading = false;
    this.alpha = 255;
  }

  update() {
    if (!this.stuck) {
      this.pos.add(this.vel);
      this.vel.rotate(random(-0.1, 0.1));

      for (let other of particles) {
        if (other !== this && other.stuck) {
          let d = dist(this.pos.x, this.pos.y, other.pos.x, other.pos.y);
          if (d < this.r * 2.5) {
            this.stuck = true;
            if (!this.hasSpawned && this.growthLimit > 0) {
              this.hasSpawned = true;
              this.spawnBranch();
            }
            // Start fading if growth is done and stuck
            if (this.growthLimit <= 0) {
              this.fading = true;
            }
            break;
          }
        }
      }

      this.pos.x = constrain(this.pos.x, 0, width);
      this.pos.y = constrain(this.pos.y, 0, height);
    } else {
      // If stuck and growth limit done, start fading
      if (this.growthLimit <= 0) {
        this.fading = true;
      }
    }

    if (this.fading) {
      this.alpha -= 1; // Adjust fade speed here (lower is slower)
      this.alpha = max(this.alpha, 0);
    }
  }

  spawnBranch() {
    let n = floor(random(2, 4));
    let newGrowthLimit = this.growthLimit - 1;

    for (let i = 0; i < n; i++) {
      var angle = random(TWO_PI);
      var r = random(4, 10);
      let newX = this.pos.x + r * cos(angle);
      let newY = this.pos.y + r * sin(angle);
      particles.push(new Particle(newX, newY, this.origin, false, newGrowthLimit));
    }
  }

  display() {
    push();
    translate(this.origin.x, this.origin.y);
    for (let i = 0; i < symmetry; i++) {
      rotate(TWO_PI / symmetry);

      stroke(red(this.hue), green(this.hue), blue(this.hue), this.alpha);
      strokeWeight(0.8);
      noFill();

      let dx = this.pos.x - this.origin.x;
      let dy = this.pos.y - this.origin.y;

      ellipse(dx, dy, this.r * 2);

      scale(1, -1);
      ellipse(dx, dy, this.r * 2);
      scale(1, -1);
    }
    pop();
  }
}

